package com.findit.servlet;
import com.findit.dao.ItemDAO;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.SQLException;
@WebServlet("/items") public class ItemsServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.sendRedirect(q.getContextPath()+"/login");return;}try{q.setAttribute("items",new ItemDAO().list(q.getParameter("type"),q.getParameter("q"),((Number)s.getAttribute("userId")).intValue(),false));q.setAttribute("search",q.getParameter("q"));q.setAttribute("type",q.getParameter("type"));q.getRequestDispatcher("/WEB-INF/views/items.jsp").forward(q,p);}catch(SQLException e){throw new ServletException(e);}}}
